insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('2528e9dc-1085-4073-b708-27781be3c524', 'c856005d-a67d-4643-a02f-3f55dcf52d3b', $$wettelijk minimumuurloon; twee economen debatteren over een verhoging$$,
   $$economie-havo-2025-i-analyse-van-het-minimumuurloon-context1.png$$,
   $$Nederland heeft een wettelijk minimumuurloon voor alle werknemers van
15 jaar en ouder. In een talkshow debatteren twee economen over de gevolgen van het verhogen van dit minimumuurloon.$$, 'inline'),
  ('f481e9b1-794d-40e8-9c47-3e5023f4565d', 'c856005d-a67d-4643-a02f-3f55dcf52d3b', $$uitspraken econoom 1 (meer economische groei) en econoom 2 (slechtere concurrentiepositie)$$,
   $$economie-havo-2025-i-analyse-van-het-minimumuurloon-context2.png$$,
   $$Econoom 1: ‘Een hoger minimumuurloon kan leiden tot meer economische groei.’
Econoom 2: ‘Een hoger minimumuurloon kan leiden tot een verslechtering van de Nederlandse internationale concurrentiepositie’.$$, 'inline'),
  ('350e7dd4-4017-4bd9-a519-2c92c0c184c7', 'c856005d-a67d-4643-a02f-3f55dcf52d3b', $$econoom 2: het minimumuurloon ligt boven het marktloon$$,
   $$economie-havo-2025-i-analyse-van-het-minimumuurloon-context3.png$$,
   $$Het debat gaat verder. Econoom 2 beweert: “Het minimumuurloon ligt boven het marktloon. Het verhogen van het minimumuurloon heeft een effect op de werkloosheid”.$$, 'inline'),
  ('174071cd-ed0f-43f4-b826-f7c7de3a7c91', 'c856005d-a67d-4643-a02f-3f55dcf52d3b', $$bij de vragen 4 en 5 worden belastingen buiten beschouwing gelaten$$,
   $$economie-havo-2025-i-analyse-van-het-minimumuurloon-context4.png$$,
   $$Bij de vragen 4 en 5 worden de belastingen buiten beschouwing gelaten.$$, 'inline'),
  ('29bd3f1c-cac7-4108-80ee-4c83e5d6940d', 'c856005d-a67d-4643-a02f-3f55dcf52d3b', $$het minimumuurloon voor jongeren hangt af van de leeftijd$$,
   $$economie-havo-2025-i-analyse-van-het-minimumuurloon-context5.png$$,
   $$Het minimumuurloon voor de jongeren (< 21 jaar) is afhankelijk van de leeftijd. Zo krijgt een 16-jarige voor hetzelfde werk een lager minimumuurloon dan een 20-jarige.$$, 'inline'),
  ('32676056-c5af-40d4-aad9-8b23431ed703', 'c856005d-a67d-4643-a02f-3f55dcf52d3b', $$een 16-jarige begint op 31 maart 2024 bij een supermarkt$$,
   $$economie-havo-2025-i-analyse-van-het-minimumuurloon-context6.png$$,
   $$Een 16-jarige begint op 31 maart 2024 met werken bij een supermarkt. Op 31 juli 2024 is deze persoon nog steeds 16 jaar.$$, 'inline'),
  ('5a79d1ba-6880-4fb5-88c8-2535dc589b1e', 'c856005d-a67d-4643-a02f-3f55dcf52d3b', $$laagconjunctuur; econoom 1 wil ook anticyclisch begrotingsbeleid$$,
   $$economie-havo-2025-i-analyse-van-het-minimumuurloon-context7.png$$,
   $$De economie van Nederland bevindt zich op het moment van het debat in een laagconjunctuur. Econoom 1 stelt dat de overheid naast het verhogen van het minimumuurloon, ook anticyclisch begrotingsbeleid kan voeren.$$, 'inline'),
  ('b6155a36-fd23-4324-bfba-227976a9ad18', 'c856005d-a67d-4643-a02f-3f55dcf52d3b', $$econoom 2: de centrale bank zet het rente-instrument in$$,
   $$economie-havo-2025-i-analyse-van-het-minimumuurloon-context8.png$$,
   $$Econoom 2 is geen voorstander van overheidsingrijpen. Tijdens een laagconjunctuur zal de inflatie lager zijn dan de inflatiedoelstelling van de centrale bank. In dat geval zal de centrale bank het rente-instrument inzetten.$$, 'inline'),
  ('a73aa7b6-0255-434f-ba47-307cdde98ba4', 'c856005d-a67d-4643-a02f-3f55dcf52d3b', $$bron 1: minimumuurloon 2024$$,
   $$economie-havo-2025-i-analyse-van-het-minimumuurloon-context9.png$$,
   $$Bron 1 Minimumuurloon 2024
leeftijd minimumuurloon per 31 maart 2024
21 jaar en ouder € 13,27
20 jaar € 10,62
19 jaar € 7,96
18 jaar € 6,64
17 jaar € 5,24
16 jaar € 4,58
15 jaar € 3,98$$, 'inline'),
  ('936778c2-7245-4cc3-a5fd-d1cfdfdc45cc', 'c856005d-a67d-4643-a02f-3f55dcf52d3b', $$bron 2: inflatie januari – juli 2024$$,
   $$economie-havo-2025-i-analyse-van-het-minimumuurloon-context10.png$$,
   $$Bron 2 Inflatie januari – juli 2024 (verandering ten opzichte van voorgaande maand)
(lijngrafiek inflatie in percentage per maand: 31 jan 1,00; 29 feb 0,59; 31 mrt 0,68; 30 apr 0,16; 31 mei 0,39; 30 jun 0,44; 31 jul 0,77)$$, 'inline'),
  ('f0b30584-6836-464d-ac0a-8a160987df2d', 'c3acb780-199b-434c-8903-b17a8d95e014', $$fietsverhuur op Bonaire: beperkt aantal verhuurbedrijven, gewone fietsen en mountainbikes$$,
   $$economie-havo-2025-i-fietsen-op-bonaire-context1.png$$,
   $$Fietsen op Bonaire wordt steeds populairder. Het wordt gezien als een gezond en duurzaam alternatief voor het vele autogebruik op het eiland. Toeristen maken graag gebruik van huurfietsen om het eiland te verkennen. Op Bonaire is een beperkt aantal fietsverhuurbedrijven actief. Zij verhuren gewone fietsen voor toeristen die op de goed aangelegde wegen willen fietsen. Daarnaast verhuren de bedrijven speciale mountainbikes aan toeristen die op zandwegen of in nationale parken willen fietsen. Ook de lokale bevolking gebruikt de huurfietsen naast de eigen fiets.$$, 'inline'),
  ('3d795e7e-6c1f-4a80-9898-daf56976493b', 'c3acb780-199b-434c-8903-b17a8d95e014', $$verhuurbedrijf Hopi Bon gaat fietsen verhuren; de directeur maakt een analyse (zie bron 1)$$,
   $$economie-havo-2025-i-fietsen-op-bonaire-context2.png$$,
   $$Verhuurbedrijf Hopi Bon wil ook fietsen gaan verhuren. Het bedrijf gaat fietsenrekken plaatsen langs de kust en in enkele binnenlandse plaatsen. Toeristen kunnen fietsen huren en betalen per dag. Ze kunnen de fietsen overal op het eiland plaatsen in de daarvoor bestemde fietsenrekken. Ze kunnen dan eventueel overstappen op een ander type fiets. Hopi Bon rekent eenzelfde prijs voor de twee typen fietsen. De directeur van Hopi Bon maakt een analyse (zie bron 1).$$, 'inline'),
  ('5f1888d5-495b-480d-bc03-8443e352d24b', 'c3acb780-199b-434c-8903-b17a8d95e014', $$Hopi Bon heeft als doelstelling maximale winst$$,
   $$economie-havo-2025-i-fietsen-op-bonaire-context3.png$$,
   $$Hopi Bon heeft als doelstelling maximale winst.$$, 'inline'),
  ('d396cb2b-1f44-4c06-bd76-4ad53df6c824', 'c3acb780-199b-434c-8903-b17a8d95e014', $$welvaart gemeten met consumenten- en producentensurplus; prijsverlaging verhoogt de welvaart$$,
   $$economie-havo-2025-i-fietsen-op-bonaire-context4.png$$,
   $$De welvaart die ontstaat op deze fietsverhuurmarkt kan worden gemeten aan de hand van het consumenten- en producentensurplus. Door een prijsverlaging stijgt de welvaart.$$, 'inline'),
  ('df34cce6-9d92-4ea4-9ef0-8e27c3ca8309', 'c3acb780-199b-434c-8903-b17a8d95e014', $$Hopi Bon wil starten met een huurprijs van $ 16 en die daarna verhogen naar $ 24$$,
   $$economie-havo-2025-i-fietsen-op-bonaire-context5.png$$,
   $$Hopi Bon wil starten met een huurprijs van $ 16, om daarna deze te verhogen naar $ 24. De directeur onderzoekt of het starten met een lage prijs ervoor zorgt dat bij een prijsverhoging de omzet zal stijgen.$$, 'inline'),
  ('e3c84e81-ec17-4976-a04c-ea4bbe33eb37', 'c3acb780-199b-434c-8903-b17a8d95e014', $$jaarabonnement voor de lokale bevolking tegen een lagere prijs per dag$$,
   $$economie-havo-2025-i-fietsen-op-bonaire-context6.png$$,
   $$De directeur wil de lokale bevolking een jaarabonnement aanbieden, zodat ook zij meer gebruik kunnen maken van de huurfietsen. Dit jaarabonnement voor de inwoners is persoonsgebonden. De inwoners betalen een lagere prijs per dag dan de toeristen.$$, 'inline'),
  ('556097e4-08b5-4873-bbe3-12350736168d', 'c3acb780-199b-434c-8903-b17a8d95e014', $$achtergelaten en beschadigde huurfietsen in Kralendijk; de directeur stelt een eigen risico in$$,
   $$economie-havo-2025-i-fietsen-op-bonaire-context7.png$$,
   $$In Kralendijk, de hoofdstad van Bonaire, worden de huurfietsen door de toeristen overal en nergens achtergelaten, behalve in de daarvoor bestemde fietsenrekken. Dit leidt tot ergernis onder de bevolking. Bovendien raken de huurfietsen hierdoor beschadigd. De directeur van Hopi Bon besluit om een eigen risico in te stellen, zodat de overlast en de schade verminderen.$$, 'inline'),
  ('237e5a8e-e160-4187-a048-f2cb46f20b4b', 'c3acb780-199b-434c-8903-b17a8d95e014', $$bron 1: financiële gegevens van Hopi Bon$$,
   $$economie-havo-2025-i-fietsen-op-bonaire-context8.png$$,
   $$Bron 1 Financiële gegevens van Hopi Bon
(grafiek: GO, MO, GTK en MK in $ tegen q; GO daalt lineair van 48 bij q = 0 tot 0 bij q = 60; MO daalt lineair van 48 bij q = 0 tot 0 bij q = 30; MK is horizontaal bij 8; GTK is een dalende curve die naar ongeveer 11 bij q = 60 loopt)
De munteenheid op Bonaire is de Amerikaanse dollar ($)
q = het aantal verhuurde fietsen per dag
GO = gemiddelde opbrengst per fiets per dag
GTK = gemiddelde totale kosten per fiets per dag
MK = marginale kosten per fiets per dag
MO = marginale opbrengst per fiets per dag$$, 'inline'),
  ('bace2ade-c97f-4dc5-82c2-17f5c85bee2d', 'e6cadec1-fd3b-4a03-9ef8-7748701e2bd5', $$EU-emissierechten: lidstaten verdelen rechten over bedrijven; rechten zijn verhandelbaar$$,
   $$economie-havo-2025-i-co2-rechten-context1.png$$,
   $$De landen van de Europese Unie (EU) hebben een akkoord gesloten waarin staat dat de uitstoot van CO₂ fors moet dalen. De EU geeft elke lidstaat een hoeveelheid CO₂-emissierechten. Een emissierecht geeft het recht tot uitstoot van één ton CO₂. De overheid van een lidstaat mag deze emissierechten verdelen onder haar bedrijven. De bedrijven kunnen de emissierechten met elkaar verhandelen. Als een bedrijf meer CO₂ wil uitstoten, moet het rechten kopen van een bedrijf dat bereid is minder CO₂ uit te stoten (dan wat het aan emissierechten van de overheid heeft gekregen).$$, 'inline'),
  ('0708c6ed-27d3-43e5-98bb-75b254b12304', 'e6cadec1-fd3b-4a03-9ef8-7748701e2bd5', $$bedrijven kunnen duurzamer produceren; een econoom onderzoekt de casus van Gas en Kolen$$,
   $$economie-havo-2025-i-co2-rechten-context2.png$$,
   $$Bedrijven kunnen ook ervoor kiezen om duurzamer te produceren waardoor zij minder emissierechten hoeven op te kopen. Een econoom onderzoekt de casus van twee bedrijven: Gas en Kolen. In het model van de econoom staan winstveranderingen voor beide bedrijven voor het komende jaar.$$, 'inline'),
  ('e88d1c5e-7989-46f4-b57f-07f4245f45c8', 'e6cadec1-fd3b-4a03-9ef8-7748701e2bd5', $$pay-offmatrix winstveranderingen in miljoenen euro's$$,
   $$economie-havo-2025-i-co2-rechten-context3.png$$,
   $$Pay-offmatrix winstveranderingen in miljoenen euro’s
(eerste getal: Gas; tweede getal: Kolen)
Gas kopen emissierechten / Kolen kopen emissierechten: −70 ; −80
Gas kopen emissierechten / Kolen investeren in duurzame productie: −50 ; −40
Gas investeren in duurzame productie / Kolen kopen emissierechten: −30 ; −60
Gas investeren in duurzame productie / Kolen investeren in duurzame productie: −35 ; −45$$, 'inline'),
  ('d96b6b1e-4e0d-43e5-8450-667a995d23bb', 'e6cadec1-fd3b-4a03-9ef8-7748701e2bd5', $$investeringen in duurzame productie leiden tot hoge verzonken kosten$$,
   $$economie-havo-2025-i-co2-rechten-context4.png$$,
   $$Investeringen in duurzame productiemethoden leiden tot hoge verzonken kosten. Hierdoor gaan bedrijven op zoek naar nieuwe markten, waardoor de totale CO₂-uitstoot niet daalt.$$, 'inline'),
  ('c18e9e05-412a-4b74-b2de-7edde1f9ac7d', 'e6cadec1-fd3b-4a03-9ef8-7748701e2bd5', $$de Nederlandse overheid geeft emissierechten vooral aan exporterende bedrijven$$,
   $$economie-havo-2025-i-co2-rechten-context5.png$$,
   $$De Nederlandse overheid geeft een groot deel van de verkregen emissierechten aan bedrijven die vooral produceren voor de export.$$, 'inline'),
  ('d9a1a9d3-ae65-4259-8b36-83afbe98589c', 'e6cadec1-fd3b-4a03-9ef8-7748701e2bd5', $$de EU verlaagt het aantal emissierechten; twee gevolgen voor het groen bbp$$,
   $$economie-havo-2025-i-co2-rechten-context6.png$$,
   $$De EU wil de daling van de CO₂-uitstoot versnellen. De EU besluit om het aantal emissierechten te verlagen, zodat er minder rechten overblijven voor bedrijven. Dit heeft twee gevolgen voor het groen bbp.$$, 'inline'),
  ('f1f71cc1-a797-4852-9b44-0281e6cf5255', 'e6cadec1-fd3b-4a03-9ef8-7748701e2bd5', $$ander systeem: prijs van emissierechten gelijk aan de maatschappelijke kosten van uitstoot$$,
   $$economie-havo-2025-i-co2-rechten-context7.png$$,
   $$Stel dat de EU besluit tot het volgende systeem van emissierechten. De EU stelt de prijs van emissierechten gelijk aan de maatschappelijke kosten die gepaard gaan met de uitstoot. Bedrijven kunnen onbeperkt rechten aankopen bij de EU tegen deze prijs. Er worden geen rechten meer gegeven door de EU.$$, 'inline'),
  ('7fb484db-1811-45c5-9559-87e9c9a6c4cb', '7b4f6f7a-1da5-4637-a5ad-7843b24d49c0', $$de AOW als basispensioen; door vergrijzing wordt de AOW-leeftijd verhoogd$$,
   $$economie-havo-2025-i-aow-leeftijd-context1.png$$,
   $$De AOW is een basispensioen voor ouderen. Door de vergrijzing verslechtert de betaalbaarheid van de AOW: er zijn minder werkenden die premie betalen waarmee de uitkeringen in dat jaar worden betaald. De Nederlandse overheid heeft daarom een aantal jaar geleden besloten de AOW-leeftijd geleidelijk te verhogen van 65 naar 67 jaar en daarna te koppelen aan de levensverwachting. De AOW-leeftijd stijgt dan mee met de gemiddelde levensverwachting.$$, 'inline'),
  ('3cc95893-2762-44a3-8c5d-eb849f8bbf39', '7b4f6f7a-1da5-4637-a5ad-7843b24d49c0', $$een onderzoeker rekent drie maatregelen door voor een AOW-leeftijd van 65 jaar (zie bron 1)$$,
   $$economie-havo-2025-i-aow-leeftijd-context2.png$$,
   $$Een deel van de bevolking wil terug naar een AOW-leeftijd van 65 jaar. Een onderzoeker analyseert hoe de extra kosten van een verlaging van de AOW-leeftijd kunnen worden gefinancierd en heeft van drie maatregelen de gevolgen doorgerekend (zie bron 1).$$, 'inline'),
  ('5a6d6c83-4f38-4a1a-a815-9fee9a271141', '7b4f6f7a-1da5-4637-a5ad-7843b24d49c0', $$de onderzoeker over maatregel 2: koopkrachtdaling van minimaal 6% voor een (echt)paar$$,
   $$economie-havo-2025-i-aow-leeftijd-context3.png$$,
   $$De onderzoeker: “Bij maatregel 2 ontvangen AOW’ers een lagere maandelijkse uitkering. Bovendien komt de koopkracht van AOW’ers verder onder druk te staan, zelfs al bij een inflatie van 1%. Voor een (echt)paar met een AOW-uitkering als enige bron van inkomsten, levert maatregel 2 een koopkrachtdaling van minimaal 6% op.”$$, 'inline'),
  ('c3fbeb14-1e55-491a-a25e-4e3ea47c8827', '7b4f6f7a-1da5-4637-a5ad-7843b24d49c0', $$de onderzoeker over maatregel 3: een paar duizend euro meer belasting in box 1$$,
   $$economie-havo-2025-i-aow-leeftijd-context4.png$$,
   $$De onderzoeker zegt over maatregel 3: “Dit leidt ertoe dat een alleenstaande oudere met een AOW-uitkering als enige inkomstenbron, jaarlijks een paar duizend euro meer belasting in box 1 moet betalen ten opzichte van de huidige situatie.”$$, 'inline'),
  ('858709ce-0b8a-48c9-9fe6-2029da9a40d5', '7b4f6f7a-1da5-4637-a5ad-7843b24d49c0', $$bron 1: maatregelen en doorrekening van de gevolgen bij verlaging van de pensioenleeftijd$$,
   $$economie-havo-2025-i-aow-leeftijd-context5.png$$,
   $$Bron 1 Maatregelen en doorrekening van de gevolgen bij verlaging van de pensioenleeftijd
maatregelen | gevolgen
1. Bespaar op de collectieve zorguitgaven door versobering van de basisverzekering. Dit betekent dat minder geneeskundige handelingen worden vergoed. Het geld dat hiermee vrijkomt, wordt gebruikt om de betaalbaarheid van de AOW te verbeteren. | A. Dit leidt op langere termijn tot hogere collectieve zorguitgaven.
2. Verlaag de AOW-uitkering tot het niveau van een bijstandsuitkering. Een bijstandsuitkering is een uitkering voor mensen die niet genoeg geld hebben om in hun levensonderhoud te voorzien, en ook niet in aanmerking komen voor een andere uitkering. | B. Er wordt € 4 miljard per jaar bespaard op de AOW-uitkeringen. Dit gaat ten koste van de koopkracht van gepensioneerden.
3. Laat iedereen de AOW-premie betalen. Dit betekent dat ook AOW’ers premie AOW gaan betalen. In de huidige situatie zijn AOW’ers hiervan vrijgesteld. | C. Dit leidt ertoe dat het netto-inkomen van alle AOW’ers daalt.$$, 'inline'),
  ('f481650e-317f-4b72-9db5-ed4f6d2ca220', '7b4f6f7a-1da5-4637-a5ad-7843b24d49c0', $$bron 2: AOW- en bijstandsuitkeringen per maand$$,
   $$economie-havo-2025-i-aow-leeftijd-context6.png$$,
   $$Bron 2 AOW- en bijstandsuitkeringen per maand
| bedrag bijstandsuitkering* | bedrag AOW-uitkering*
alleenstaande | € 1.195,66 | € 1.330,76
(echt)paar | € 1.708,08 | € 1.807,20
* De bedragen zijn inclusief vakantiegeld.$$, 'inline'),
  ('b29a2478-59f7-4d96-b10f-3cc880a27315', '7b4f6f7a-1da5-4637-a5ad-7843b24d49c0', $$bron 3: tarieven box 1 niet-AOW'ers en AOW'ers$$,
   $$economie-havo-2025-i-aow-leeftijd-context7.png$$,
   $$Bron 3 tarieven box 1 niet-AOW’ers en AOW’ers
niet-AOW’ers
schijf | belastbaar inkomen per jaar | tarief
1 | tot € 73.032 | 36,93%
2 | vanaf € 73.032 | 49,50%
AOW’ers
schijf | belastbaar inkomen per jaar | tarief
1 | tot € 38.704 | 19,03%*
2 | vanaf € 38.704 tot € 73.032 | 36,93%
3 | vanaf € 73.032 | 49,50%
* AOW’ers betalen geen AOW-premie, waardoor hun tarief over de eerste € 38.704 19,03% is in plaats van 36,93%.$$, 'inline'),
  ('f4868bbb-402e-4dc4-9330-4e5eec512889', '22f3b2b6-e428-48f4-ab0a-479a502096d5', $$verzekeraars gebruiken artificiële intelligentie bij het beoordelen van individuele risico's$$,
   $$economie-havo-2025-i-ai-in-de-verzekeringssector-context1.png$$,
   $$Door de steeds grotere beschikbaarheid van gegevens en de sterk toegenomen rekenkracht van computers heeft artificiële intelligentie (AI) zich sinds 2023 snel ontwikkeld. Met behulp van artificiële intelligentie kunnen grote hoeveelheden gegevens worden geanalyseerd. Steeds meer verzekeraars maken gebruik van artificiële intelligentie bij het beoordelen van individuele risico’s van verzekerden en daardoor bij het vaststellen van een premie per verzekerde.$$, 'inline'),
  ('32adb161-ea12-40c1-bae5-8741502464a8', '22f3b2b6-e428-48f4-ab0a-479a502096d5', $$risico-inschatting werkt door in de premie; mogelijk minder averechtse selectie$$,
   $$economie-havo-2025-i-ai-in-de-verzekeringssector-context2.png$$,
   $$De risico-inschatting door verzekeraars werkt vervolgens door in de premie. Dit zou kunnen leiden tot een vermindering van averechtse selectie.$$, 'inline'),
  ('eb8cfca4-157a-4f57-ba31-73db6859806b', '22f3b2b6-e428-48f4-ab0a-479a502096d5', $$toezichthouder: gepersonaliseerde premies zetten solidariteit onder druk$$,
   $$economie-havo-2025-i-ai-in-de-verzekeringssector-context3.png$$,
   $$Een toezichthouder financiële markten doet de volgende uitspraak: “Als verzekeraars artificiële intelligentie inzetten om premies te personaliseren op basis van het individuele risicoprofiel van verzekerden, kan de solidariteit tussen verzekerden onder druk komen te staan”.$$, 'inline'),
  ('9911c507-4013-4fd8-be4b-e03692c1be74', '22f3b2b6-e428-48f4-ab0a-479a502096d5', $$vooral buitenlandse verzekeraars trekken met AI gerichter de goede risico's aan$$,
   $$economie-havo-2025-i-ai-in-de-verzekeringssector-context4.png$$,
   $$Uit onderzoek blijkt dat vooral buitenlandse verzekeraars gebruik maken van artificiële intelligentie om data te analyseren en daarmee gerichter de goede risico’s aantrekken.$$, 'inline');

